import java.lang.IllegalArgumentException;
public enum EnumStudy { JAVA(1), C(2),RUBY(3); private int value; public int intValue() { return value;} private EnumStudy(int value) { this.value = value; } public static EnumStudy valueOf(int value) { switch (value) { case 1: return JAVA; case 2: return C; case 3: return RUBY; default: throw new IllegalArgumentException(&ldquo;There is no matching for &ldquo;+value); } }
public static void main(String args[]) { System.out.println(EnumStudy.valueOf(1)); System.out.println(EnumStudy.valueOf(&ldquo;JAVA&rdquo;)); //이건 enum들은 기본적으로 선언되는 메소드.
